import { parseTest2Arguments } from './lib/cli/index.mjs';
import { ID, KEYWORD, NUMERIC, Schema, TEXT } from './lib/whoosh/index.mjs';

export function main(argv = process.argv.slice(2)) {
  const parseResult = parseTest2Arguments(argv);

  if (parseResult.kind === 'help') {
    process.stdout.write(parseResult.message);
    process.exitCode = parseResult.exitCode;
    return;
  }

  if (parseResult.kind === 'error') {
    process.stderr.write(parseResult.message);
    process.exitCode = parseResult.exitCode;
    return;
  }

  const args = parseResult.args;
  void args;

  const schema = new Schema({
    id: ID({ stored: true }),
    title: TEXT({ stored: true }),
    tags: KEYWORD,
    price: NUMERIC({ stored: true }),
  });

  process.stdout.write(`${schema.toString()}\n`);
}

main();

