import { normalizeFieldDefinition } from './fields.mjs';

export class Schema {
  constructor(definitions = {}) {
    this.fields = {};

    for (const [name, definition] of Object.entries(definitions)) {
      this.fields[name] = normalizeFieldDefinition(definition);
    }
  }

  toString() {
    const renderedNames = Object.keys(this.fields)
      .sort()
      .map((fieldName) => `'${fieldName}'`)
      .join(', ');

    return `<Schema: [${renderedNames}]>`;
  }
}

