import {
  NEGATIVE_NUMBER_PATTERN,
  OPTION_A,
  OPTION_A_PREFIX,
  OPTION_HELP,
  OPTION_HELP_SHORT,
  OPTION_TERMINATOR,
  PROGRAM_NAME,
} from './constants.mjs';
import {
  formatExpectedOneArgumentError,
  formatHelp,
  formatMissingRequiredError,
  formatUnrecognizedArgumentsError,
} from './messages.mjs';

export function parseTest2Arguments(argv, programName = PROGRAM_NAME) {
  let aValue;
  const unknownTokens = [];
  let parsingOptions = true;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (!parsingOptions) {
      unknownTokens.push(token);
      continue;
    }

    if (isHelpToken(token)) {
      return {
        kind: 'help',
        message: formatHelp(programName),
        exitCode: 0,
      };
    }

    if (token === OPTION_TERMINATOR) {
      parsingOptions = false;
      unknownTokens.push(token);
      continue;
    }

    if (token === OPTION_A) {
      const nextToken = argv[index + 1];
      if (nextToken === undefined || isMissingOptionValue(nextToken)) {
        return {
          kind: 'error',
          message: formatExpectedOneArgumentError(programName),
          exitCode: 2,
        };
      }

      aValue = nextToken;
      index += 1;
      continue;
    }

    if (token.startsWith(OPTION_A_PREFIX)) {
      aValue = token.slice(OPTION_A_PREFIX.length);
      continue;
    }

    unknownTokens.push(token);
  }

  if (aValue === undefined) {
    return {
      kind: 'error',
      message: formatMissingRequiredError(programName),
      exitCode: 2,
    };
  }

  if (unknownTokens.length > 0) {
    return {
      kind: 'error',
      message: formatUnrecognizedArgumentsError(programName, unknownTokens),
      exitCode: 2,
    };
  }

  return {
    kind: 'ok',
    args: { a: aValue },
    exitCode: 0,
  };
}

export function isHelpToken(token) {
  if (token === OPTION_HELP_SHORT) {
    return true;
  }

  if (!token.startsWith('--') && token.startsWith(OPTION_HELP_SHORT)) {
    return true;
  }

  return token.length > OPTION_TERMINATOR.length && OPTION_HELP.startsWith(token);
}

export function isMissingOptionValue(token) {
  if (token === OPTION_TERMINATOR) {
    return true;
  }

  if (token.startsWith('--')) {
    return true;
  }

  return token.startsWith('-') && !NEGATIVE_NUMBER_PATTERN.test(token);
}

