export class FieldDefinition {
  constructor(typeName, options = {}) {
    this.typeName = typeName;
    this.options = { ...options };
  }
}

export function createFieldFactory(typeName) {
  const factory = (options = {}) => new FieldDefinition(typeName, options);
  factory.typeName = typeName;
  return factory;
}

export const TEXT = createFieldFactory('TEXT');
export const ID = createFieldFactory('ID');
export const KEYWORD = createFieldFactory('KEYWORD');
export const NUMERIC = createFieldFactory('NUMERIC');

export function normalizeFieldDefinition(definition) {
  if (definition instanceof FieldDefinition) {
    return definition;
  }

  if (typeof definition === 'function' && typeof definition.typeName === 'string') {
    return definition();
  }

  throw new TypeError('Unsupported field definition');
}

